export function toolsText(lang:string,key:string){
  const row=(toolsRows as any)[lang]||(toolsRows as any).it;
  const baseIndex=(keys as readonly string[]).indexOf(key);
  if(baseIndex>=0)return row[baseIndex];
  return moveToToolsRows[lang]?.[key]||redesignRows[lang]?.[key]||enhancedRows[lang]?.[key]||extraRows[lang]?.[key]||moveToToolsRows.it?.[key]||redesignRows.it?.[key]||enhancedRows.it?.[key]||extraRows.it?.[key]||key;
}
